SELECT id, stat_date, virtual_key_id, tool_or_model, channel_id,
       call_count, fail_count, total_duration_ms, token_sum, updated_at
FROM mcp_usage_daily


        AND stat_date >= #{fromDate}


        AND stat_date <= #{toDate}


ORDER BY stat_date ASC, call_count DESC

SELECT NULL AS id, stat_date, 0 AS virtual_key_id, '' AS tool_or_model, '' AS channel_id, SUM(call_count) AS call_count, SUM(fail_count) AS fail_count, SUM(total_duration_ms) AS total_duration_ms, SUM(token_sum) AS token_sum, NULL AS updated_at FROM mcp_usage_daily
AND stat_date >= #{fromDate}
AND stat_date <= #{toDate}
GROUP BY stat_date ORDER BY stat_date ASC

SELECT COALESCE(SUM(cost), 0)
FROM mcp_usage_log
WHERE virtual_key_id = #{virtualKeyId}
  AND cost IS NOT NULL
  AND created_at >= #{since}
